/*
 * Vigyanshaala site chrome for frontend-base MFEs (e.g. progress).
 *
 * Generated by tutor-vigyanshaala-theme-plugin -- do not edit in the MFE.
 *
 * frontend-base MFEs do not load env.config.jsx or frontend-plugin-framework
 * slots, so the plugin cannot inject its header and footer the way it does
 * for the other MFEs.  Instead this module reuses the very same component
 * files (IndigoFooter.jsx, CustomHeaderNav.jsx, CustomHeaderUserMenuItem.jsx,
 * CustomHeaderUserMenuDropdown.jsx) and plugs them into the frontend-base
 * shell's header/footer slots.  It provides the small part of the
 * frontend-platform API those components use (getConfig, AppContext, ...),
 * with the config read from Tutor's MFE config API exactly like the other
 * MFEs.  Edit those component files, not this one, to change a link or menu.
 *
 * The MFE build copies this directory over the MFE's src/site-chrome/ (see
 * the mfe-dockerfile-pre-npm-build-<mfe> patch in plugin.py).
 */
import React, { useContext, useEffect, useRef, useState } from 'react';
import classNames from 'classnames';
import {
  getAuthenticatedHttpClient, getSiteConfig, getUrlByRouteRole, useAuthenticatedUser, useIntl, WidgetOperationTypes,
} from '@openedx/frontend-base';
import { Dropdown, Icon, Nav } from '@openedx/paragon';
import {
  AccountCircle, ExpandMore, LocationOn, Mail, Phone,
} from '@openedx/paragon/icons';

// vs-brand colours, installed as @edx/brand by the mfe-dockerfile-post-npm-install-<mfe> patch.
import '@edx/brand/dist/light.min.css';
import './site-chrome.css';

// ---------------------------------------------------------------------------
// frontend-platform API used by the shared components
// ---------------------------------------------------------------------------

// The MFE's id is the first path segment (Tutor serves each MFE at /<app>/).
const vsAppId = window.location.pathname.split('/').filter(Boolean)[0] || '';

// Used until the MFE config API answers (or if it cannot be reached).
const vsFallbackConfig = () => {
  const site = getSiteConfig();
  return {
    LMS_BASE_URL: site.lmsBaseUrl,
    STUDIO_BASE_URL: site.cmsBaseUrl,
    LOGO_URL: site.headerLogoImageUrl,
    LOGO_WHITE_URL: site.headerLogoImageUrl,
    LOGOUT_URL: site.logoutUrl,
    SITE_NAME: site.siteName,
    CATALOG_MICROFRONTEND_URL: `${window.location.origin}/public/`,
    ACCOUNT_PROFILE_URL: (getUrlByRouteRole('org.openedx.frontend.role.profile') || '').replace(/\/$/, ''),
    ACCOUNT_SETTINGS_URL: getUrlByRouteRole('org.openedx.frontend.role.account'),
  };
};

let vsMfeConfig = null;
let vsMfeConfigRequest = null;
const vsConfigListeners = new Set();

// Same per-MFE configuration the other MFEs get (MFE_CONFIG + MFE_CONFIG_OVERRIDES["<app>"]).
const vsLoadMfeConfig = () => {
  if (!vsMfeConfigRequest) {
    vsMfeConfigRequest = fetch(`/api/mfe_config/v1?mfe=${encodeURIComponent(vsAppId)}`, {
      headers: { accept: 'application/json' },
    })
      .then((response) => (response.ok ? response.json() : {}))
      .catch(() => ({}))
      .then((data) => {
        // Unset values in the API answer (e.g. no MFE_CONFIG_OVERRIDES entry yet) keep the fallback.
        const defined = Object.fromEntries(Object.entries(data || {}).filter(([, value]) => value != null && value !== ''));
        vsMfeConfig = { ...vsFallbackConfig(), ...defined };
        vsConfigListeners.forEach((listener) => listener());
      });
  }
  return vsMfeConfigRequest;
};

const getConfig = () => vsMfeConfig || vsFallbackConfig();

const AppContext = React.createContext({ authenticatedUser: null, config: {} });

// The frontend-base shell does not load the account details; the header shows the profile picture.
const vsAvatarRequests = {};
const vsLoadAvatar = (username) => {
  if (!vsAvatarRequests[username]) {
    vsAvatarRequests[username] = getAuthenticatedHttpClient()
      .get(`${getConfig().LMS_BASE_URL}/api/user/v1/accounts/${encodeURIComponent(username)}`)
      .then(({ data }) => (data?.profile_image?.has_image ? data.profile_image.image_url_medium : null))
      .catch(() => null);
  }
  return vsAvatarRequests[username];
};

const useVsAppContextValue = () => {
  const user = useAuthenticatedUser();
  const [, setConfigVersion] = useState(0);
  const [avatar, setAvatar] = useState(null);

  useEffect(() => {
    const listener = () => setConfigVersion((version) => version + 1);
    vsConfigListeners.add(listener);
    vsLoadMfeConfig();
    return () => { vsConfigListeners.delete(listener); };
  }, []);

  useEffect(() => {
    let active = true;
    if (user?.username) {
      vsLoadAvatar(user.username).then((url) => { if (active) { setAvatar(url); } });
    }
    return () => { active = false; };
  }, [user?.username]);

  return {
    authenticatedUser: user ? { ...user, avatar: user.avatar || avatar } : null,
    config: getConfig(),
  };
};

// Renders a shared component with the frontend-platform context it expects.
const withVsChrome = (Component, className) => function VsChromeWidget() {
  const value = useVsAppContextValue();
  return (
    <AppContext.Provider value={value}>
      <div className={classNames('vs-site-chrome', className)}>
        <Component />
      </div>
    </AppContext.Provider>
  );
};

// ---------------------------------------------------------------------------
// Shared components (same files as in env.config.jsx of the other MFEs)
// ---------------------------------------------------------------------------
{{ patch("IndigoFooter.jsx") }}
{{ patch("CustomHeaderNav.jsx") }}
{{ patch("CustomHeaderUserMenuItem.jsx") }}
{{ patch("CustomHeaderUserMenuDropdown.jsx") }}

// ---------------------------------------------------------------------------
// frontend-base renderings of frontend-component-header's parts
// ---------------------------------------------------------------------------

// The header logo of the other MFEs: LOGO_URL, linking to the LMS dashboard.
const VsHeaderLogo = () => {
  const config = getConfig();
  return (
    <a className="logo" href={`${config.LMS_BASE_URL}/dashboard`}>
      <img className="d-block" src={config.LOGO_URL} alt={config.SITE_NAME || ''} />
    </a>
  );
};

// The main menu built by modifyMainMenu (CustomHeaderNav.jsx).
const useVsMainMenu = () => modifyMainMenu({ content: { menu: [] } }).content.menu;

const VsDesktopMainMenu = () => {
  const menu = useVsMainMenu();
  return (
    <Nav as="nav" className="nav main-nav">
      {menu.map((item, index) => (item.type === 'menu' ? (
        // eslint-disable-next-line react/no-array-index-key
        <Dropdown key={index} className="menu nav-item">
          <Dropdown.Toggle variant="link" className="menu-trigger nav-link">
            {item.content}
            <Icon src={ExpandMore} className="vs-menu-chevron" />
          </Dropdown.Toggle>
          <Dropdown.Menu>{item.submenuContent}</Dropdown.Menu>
        </Dropdown>
      ) : (
        // eslint-disable-next-line react/no-array-index-key
        <a key={index} href={item.href} className={classNames('nav-link', { active: item.isActive })}>
          {item.content}
        </a>
      )))}
    </Nav>
  );
};

// Phones: the shell's hamburger menu, with sub-menus listed inline.
const VsMobileMainMenu = () => {
  const menu = useVsMainMenu();
  return (
    <Nav as="nav" className="nav flex-column vs-mobile-nav">
      {menu.map((item, index) => (item.type === 'menu' ? (
        // eslint-disable-next-line react/no-array-index-key
        <div key={index} className="vs-mobile-submenu">{item.submenuContent}</div>
      ) : (
        // eslint-disable-next-line react/no-array-index-key
        <a key={index} href={item.href} className={classNames('nav-link', { active: item.isActive })}>
          {item.content}
        </a>
      )))}
    </Nav>
  );
};

// User menu: DesktopUserMenuToggleAvatar as the toggle, CustomHeaderUserMenuItem as the items.
const VsUserMenu = () => (
  <Dropdown className="menu vs-user-menu">
    <Dropdown.Toggle variant="outline-primary" className="menu-trigger">
      <DesktopUserMenuToggleAvatar />
    </Dropdown.Toggle>
    <Dropdown.Menu align="right">
      <CustomHeaderUserMenuItem />
    </Dropdown.Menu>
  </Dropdown>
);

// ---------------------------------------------------------------------------
// frontend-base app: replaces the shell's header and footer widgets
// ---------------------------------------------------------------------------
/** @type {import('@openedx/frontend-base').App} */
const siteChromeApp = {
  appId: 'org.vigyanshaala.frontend.app.siteChrome',
  slots: [
    // Desktop header
    {
      slotId: 'org.openedx.frontend.slot.header.desktopLeft.v1',
      id: 'org.vigyanshaala.frontend.widget.header.desktopLogo.v1',
      relatedId: 'org.openedx.frontend.widget.header.desktopLogo.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(VsHeaderLogo),
    },
    {
      slotId: 'org.openedx.frontend.slot.header.desktopLeft.v1',
      id: 'org.vigyanshaala.frontend.widget.header.desktopMainMenu.v1',
      relatedId: 'org.openedx.frontend.widget.header.desktopPrimaryLinks.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(VsDesktopMainMenu),
    },
    {
      slotId: 'org.openedx.frontend.slot.header.desktopRight.v1',
      id: 'org.vigyanshaala.frontend.widget.header.desktopUserMenu.v1',
      relatedId: 'org.openedx.frontend.widget.header.desktopAuthenticatedMenu.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(VsUserMenu),
      condition: { authenticated: true },
    },
    // Mobile header
    {
      slotId: 'org.openedx.frontend.slot.header.mobileCenter.v1',
      id: 'org.vigyanshaala.frontend.widget.header.mobileLogo.v1',
      relatedId: 'org.openedx.frontend.widget.header.mobileLogo.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(VsHeaderLogo),
    },
    {
      slotId: 'org.openedx.frontend.slot.header.mobileMenuLinks.v1',
      id: 'org.vigyanshaala.frontend.widget.header.mobileMainMenu.v1',
      op: WidgetOperationTypes.APPEND,
      component: withVsChrome(VsMobileMainMenu),
    },
    {
      slotId: 'org.openedx.frontend.slot.header.mobileRight.v1',
      id: 'org.vigyanshaala.frontend.widget.header.mobileUserMenu.v1',
      relatedId: 'org.openedx.frontend.widget.header.mobileAuthenticatedMenu.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(VsUserMenu),
      condition: { authenticated: true },
    },
    // Footer
    {
      slotId: 'org.openedx.frontend.slot.footer.desktop.v1',
      id: 'org.vigyanshaala.frontend.widget.footer.v1',
      relatedId: 'org.openedx.frontend.widget.footer.desktopLayout.v1',
      op: WidgetOperationTypes.REPLACE,
      component: withVsChrome(IndigoFooter),
    },
  ],
};

// Site font, as in the other MFEs (vs-brand _fonts.scss).
if (typeof document !== 'undefined' && !document.getElementById('vs-site-chrome-font')) {
  const fontLink = document.createElement('link');
  fontLink.id = 'vs-site-chrome-font';
  fontLink.rel = 'stylesheet';
  fontLink.href = 'https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;500;600;700;800&display=swap';
  document.head.appendChild(fontLink);
}

export default siteChromeApp;
